const { spawnSync, spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');

// --- Detach: re-exec ourselves as a background worker, then return at once. ---
// stdio MUST be 'ignore'. Inheriting or piping keeps the harness's pipe open,
// so it would wait for the child anyway and we would have rebuilt the timeout
// with extra steps. The lock below is then taken by the WORKER's pid, which is
// what isProcessAlive() needs in order to coordinate late-arriving sessions.
if (!process.argv.includes('--worker')) {
  try {
    spawn(process.execPath, [__filename, '--worker'], {
      detached: true,
      stdio: 'ignore',
    }).unref();
  } catch (_) {}
  process.exit(0);
}

// Declared before resolvePaths() runs: `const PATHS = resolvePaths()` executes
// below, and resolvePaths now calls logErr on the fallback branch. If ERR_LOG
// were still declared further down it would be in the temporal dead zone at
// that moment, and logErr's own try/catch would swallow the ReferenceError —
// turning the loud fallback warning silent again.
  // Lock exists. If its owner is alive, skip regardless of age. Only reclaim a
  // dead owner (or an old lock with no readable owner PID).
  let ownerPid = null;
  try {
    ownerPid = Number.parseInt(fs.readFileSync(LOCK_FILE, 'utf8').trim(), 10);
  } catch (_) {}
  if (isProcessAlive(ownerPid)) process.exit(0);

  let stale = false;
  try { stale = (Date.now() - fs.statSync(LOCK_FILE).mtimeMs) >= LOCK_STALE_MS; }
  catch (_) { stale = true; } // lock vanished between open and stat — race; treat as reclaimable
  if (!stale) process.exit(0);
  try {
    fs.unlinkSync(LOCK_FILE);
    const fd = fs.openSync(LOCK_FILE, 'wx');
    fs.writeSync(fd, String(process.pid));
    fs.closeSync(fd);
    haveLock = true;
  }
  catch (_) { process.exit(0); }
}

function releaseLock() {
  if (haveLock) { try { fs.unlinkSync(LOCK_FILE); } catch (_) {} haveLock = false; }
}

try {
  const res = spawnSync('memsearch', ['index', ...existing], {
    // Avoid an intermediate cmd.exe. On timeout, the direct child is killed
    // instead of leaving an orphaned Python indexer behind.
    shell: false,
    windowsHide: true,
    encoding: 'utf8',
    // memsearch can print more than Node's 1 MiB default during a large
    // incremental catch-up. Preserve its output and exit status for diagnosis.
    maxBuffer: 32 * 1024 * 1024,

